//! Explicit correctness driver for a fresh production Worker, optionally owned
//! by this Rust driver through GIT_ZERO_HISTORY_OWN_RUNTIME.
//! No benchmark/scorer inputs or timings are generated by this test.
use git_zero_host::native::command;
use serde_json::Value;
use std::fs::{self, File};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::Duration;

fn run(program: &str, args: &[&str], input: &[u8]) -> Vec<u8> {
    let mut process = Command::new(program);
    process.args(args);
    command(process, input)
        .unwrap_or_else(|error| panic!("{program} {args:?}: {error}"))
        .stdout
}
fn git(repo: &Path, args: &[&str], input: &[u8]) -> Vec<u8> {
    let mut all = vec!["-C", repo.to_str().unwrap()];
    all.extend(args);
    run("git", &all, input)
}
fn text(repo: &Path, args: &[&str], input: &[u8]) -> String {
    String::from_utf8(git(repo, args, input))
        .unwrap()
        .trim()
        .into()
}
fn packet(line: &str) -> Vec<u8> {
    format!("{:04x}{line}", line.len() + 4).into_bytes()
}
fn fetch(want: &str, have: Option<&str>, capabilities: &str) -> Vec<u8> {
    let mut body = packet(&format!("want {want}{capabilities}\n"));
    body.extend_from_slice(b"0000");
    if let Some(have) = have {
        body.extend(packet(&format!("have {have}\n")));
    }
    body.extend(packet("done\n"));
    body
}
fn http(root: &Path, name: &str, url: &str, body: Option<&[u8]>) -> Vec<u8> {
    let headers = root.join(format!("{name}.headers"));
    let mut args = vec![
        "--silent",
        "--show-error",
        "--fail-with-body",
        "--max-time",
        "120",
        "--http1.1",
        "--dump-header",
        headers.to_str().unwrap(),
        url,
    ];
    let input = root.join(format!("{name}.request"));
    let body_arg;
    if let Some(body) = body {
        fs::write(&input, body).unwrap();
        body_arg = format!("@{}", input.display());
        args.extend([
            "-H",
            if url.ends_with("/git-receive-pack") {
                "Content-Type: application/x-git-receive-pack-request"
            } else {
                "Content-Type: application/x-git-upload-pack-request"
            },
            "--data-binary",
            &body_arg,
        ]);
    }
    let result = run("curl", &args, &[]);
    fs::write(root.join(format!("{name}.body")), &result).unwrap();
    result
}
fn metrics(root: &Path, name: &str, native: &str, stats: bool) -> Value {
    serde_json::from_slice(&http(
        root,
        name,
        &format!(
            "{native}/{}",
            if stats { "_object-stats" } else { "metrics" }
        ),
        None,
    ))
    .unwrap()
}
fn n(value: &Value, field: &str) -> u64 {
    value[field]
        .as_u64()
        .unwrap_or_else(|| panic!("missing {field}: {value}"))
}
fn usage(value: &Value, field: &str) -> u64 {
    n(&value["cloudflare_services"], field)
}
fn assert_no_storage_growth(before: &Value, after: &Value) {
    for field in [
        "r2_written_bytes",
        "r2_live_objects",
        "r2_live_bytes",
        "r2_peak_bytes",
        "do_sqlite_bytes",
        "do_rows_written",
    ] {
        assert_eq!(usage(before, field), usage(after, field), "{field}");
    }
}
fn assert_projection(value: &Value) {
    assert_eq!(value["native_view"]["scope"], "projection", "{value}");
    assert!(n(&value["native_view"], "selected_packs") < n(&value["native_view"], "total_packs"));
    assert!(n(value, "history_lineage_bytes") > 0);
    assert!(n(value, "cache_retained_bytes") <= 32 * 1024 * 1024);
}
fn accept_pack(client: &Path, response: &[u8], wanted: &str) {
    let at = response
        .windows(4)
        .position(|window| window == b"PACK")
        .expect("native pack response");
    git(
        client,
        &["index-pack", "--stdin", "--strict", "--fix-thin"],
        &response[at..],
    );
    assert_eq!(text(client, &["cat-file", "-t", wanted], &[]), "commit");
}
fn commit(
    source: &Path,
    parent: Option<&str>,
    old_blob: &str,
    extra_blob: Option<&str>,
    revision: usize,
) -> String {
    let blob = text(
        source,
        &["hash-object", "-w", "--stdin"],
        format!("revision {revision}\n").as_bytes(),
    );
    let mut rows = format!("100644 blob {old_blob}\tpayload\n100644 blob {blob}\trevision\n");
    if let Some(blob) = extra_blob {
        rows.push_str(&format!("100644 blob {blob}\textra\n"));
    }
    let tree = text(source, &["mktree"], rows.as_bytes());
    let mut args = vec![
        "-c",
        "user.name=History contract",
        "-c",
        "user.email=history@example.invalid",
        "commit-tree",
        &tree,
    ];
    if let Some(parent) = parent {
        args.extend(["-p", parent]);
    }
    text(source, &args, format!("revision {revision}\n").as_bytes())
}
fn payload(bytes: usize, mut state: u64) -> Vec<u8> {
    (0..bytes)
        .map(|_| {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state as u8
        })
        .collect()
}
struct Native(Child);
impl Drop for Native {
    fn drop(&mut self) {
        // This child starts its own session, so only its codec/Git process group is
        // stopped. The separately managed Worker is never targeted by this driver.
        let _ = Command::new("kill")
            .args(["-TERM", "--", &format!("-{}", self.0.id())])
            .status();
        let _ = self.0.wait();
    }
}

struct RuntimeDrop(Child);
impl RuntimeDrop {
    fn start(root: &Path, origin: &str) -> Self {
        assert_eq!(origin, "http://127.0.0.1:8834");
        let reservation = std::net::TcpListener::bind("127.0.0.1:8834")
            .expect("owned Worker port 8834 must be free");
        let worker = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("cloudflare");
        let config = fs::read_to_string(worker.join("wrangler.toml"))
            .unwrap()
            .replace(
                "main = \"src/index.js\"",
                &format!("main = {:?}", worker.join("src/index.js")),
            );
        let config_path = root.join("wrangler.toml");
        fs::write(&config_path, config).unwrap();
        let cli = std::env::var_os("GIT_ZERO_HISTORY_WRANGLER")
            .map(PathBuf::from)
            .unwrap_or_else(|| worker.join("node_modules/wrangler/bin/wrangler.js"));
        let log_path = root.join("wrangler.log");
        let log = File::create(&log_path).unwrap();
        drop(reservation);
        let child = Command::new("setsid")
            .arg("node")
            .arg(cli)
            .args(["dev", "--config"])
            .arg(config_path)
            .args([
                "--ip",
                "127.0.0.1",
                "--port",
                "8834",
                "--local",
                "--persist-to",
            ])
            .arg(root.join("persist"))
            .arg("--show-interactive-dev-session=false")
            .current_dir(root)
            .env("WRANGLER_SEND_METRICS", "false")
            .env("X_LOCAL_EXPLORER", "false")
            .env("X_LOCAL_OBSERVABILITY", "false")
            .env("BROWSER", "none")
            .env("WRANGLER_LOG_PATH", root.join("logs"))
            .stdin(Stdio::null())
            .stdout(Stdio::from(log.try_clone().unwrap()))
            .stderr(Stdio::from(log))
            .spawn()
            .unwrap();
        let mut runtime = Self(child);
        for _ in 0..200 {
            assert!(
                runtime.0.try_wait().unwrap().is_none(),
                "Worker exited; inspect {}",
                log_path.display()
            );
            if fs::read_to_string(&log_path)
                .unwrap()
                .contains(&format!("Ready on {origin}"))
            {
                return runtime;
            }
            std::thread::sleep(Duration::from_millis(100));
        }
        panic!(
            "Worker did not become ready; inspect {}",
            log_path.display()
        );
    }
}
impl Drop for RuntimeDrop {
    fn drop(&mut self) {
        let _ = Command::new("kill")
            .args(["-TERM", "--", &format!("-{}", self.0.id())])
            .status();
        let _ = self.0.wait();
    }
}

fn real_history_fetch(
    root: &Path,
    source: &Path,
    native: &str,
    gateway: &str,
    wanted: &str,
    have: Option<&str>,
) -> Value {
    let name = if have.is_some() {
        "real-with-haves"
    } else {
        "real-no-haves"
    };
    let client = root.join(format!("{name}.git"));
    fs::create_dir(&client).unwrap();
    git(
        &client,
        &["init", "--bare", "--quiet", "--initial-branch=main"],
        &[],
    );
    git(&client, &["config", "fetch.unpackLimit", "1"], &[]);
    git(&client, &["config", "gc.auto", "0"], &[]);
    if let Some(have) = have {
        git(
            &client,
            &[
                "fetch",
                "--quiet",
                "--no-tags",
                "--keep",
                source.to_str().unwrap(),
                &format!("{have}:refs/heads/seed"),
            ],
            &[],
        );
    }
    let before = metrics(root, &format!("{name}-before"), native, false);
    let trace_path = root.join(format!("{name}.packet-trace"));
    let mut process = Command::new("git");
    process
        .args([
            "-C",
            client.to_str().unwrap(),
            "-c",
            "protocol.version=0",
            "fetch",
            "--quiet",
            "--no-tags",
            "--keep",
            gateway,
            &format!("{wanted}:refs/heads/result"),
        ])
        // Packet tracing is client-only: Native identity must see the CI policy.
        .env("GIT_TRACE_PACKET", &trace_path);
    let output = command(process, &[]).unwrap();
    fs::write(root.join(format!("{name}.stderr")), output.stderr).unwrap();
    let after = metrics(root, &format!("{name}-after"), native, false);
    assert_eq!(
        text(&client, &["rev-parse", "refs/heads/result"], &[]),
        wanted
    );
    git(&client, &["fsck", "--strict", "--full"], &[]);
    assert_eq!(
        git(source, &["archive", "--format=tar", wanted], &[]),
        git(&client, &["archive", "--format=tar", wanted], &[])
    );
    let trace = fs::read_to_string(&trace_path).unwrap();
    let want = trace
        .lines()
        .find(|line| line.contains("want ") && line.contains("agent="))
        .expect("real client first want with capabilities");
    assert!(
        want.contains(" deepen-since ") && want.contains(" deepen-not "),
        "{want}"
    );
    assert!(
        !want.contains(" include-tag "),
        "--no-tags must retain the supported capability policy"
    );
    if let Some(have) = have {
        assert!(
            trace.contains(&format!("have {have}")),
            "real client must negotiate its seed"
        );
    }
    assert_no_storage_growth(&before, &after);
    let read_bytes = usage(&after, "r2_read_bytes") - usage(&before, "r2_read_bytes");
    let full_bytes = n(&after["native_view"], "total_bytes");
    let projected = after["native_view"]["scope"] == "projection"
        && n(&after, "history_projections") == n(&before, "history_projections") + 1
        && read_bytes == n(&after["native_view"], "selected_bytes")
        && read_bytes > 0
        && read_bytes < full_bytes;
    let receipt = serde_json::json!({"client":"real Git protocol v0", "name":name,"want":wanted,"have":have,
        "first_want_trace":want,"before":before,"after":after,"actual_r2_read_bytes":read_bytes,
        "full_bytes":full_bytes,"projected":projected,"fsck_strict":true,"archive_identical":true});
    fs::write(
        root.join(format!("{name}-receipt.json")),
        serde_json::to_vec_pretty(&receipt).unwrap(),
    )
    .unwrap();
    receipt
}

#[test]
#[ignore = "requires explicit local Worker origin; GIT_ZERO_HISTORY_OWN_RUNTIME=1 owns fresh port 8834"]
fn production_history_prefix_contract() {
    let origin =
        std::env::var("GIT_ZERO_HISTORY_CLOUDFLARE_ORIGIN").expect("explicit local Worker origin");
    assert!(matches!(
        origin.as_str(),
        "http://127.0.0.1:8831" | "http://127.0.0.1:8834"
    ));
    let root = PathBuf::from(
        std::env::var("GIT_ZERO_HISTORY_ARTIFACTS")
            .unwrap_or_else(|_| "/tmp/git-zero-history-prefix-production".into()),
    );
    fs::create_dir(&root).expect("fresh driver artifacts directory");
    let _runtime = std::env::var_os("GIT_ZERO_HISTORY_OWN_RUNTIME")
        .map(|_| RuntimeDrop::start(&root, &origin));
    let source = root.join("source.git");
    let client = root.join("client.git");
    fs::create_dir(&source).unwrap();
    fs::create_dir(&client).unwrap();
    for repo in [&source, &client] {
        git(
            repo,
            &["init", "--bare", "--quiet", "--initial-branch=main"],
            &[],
        );
    }
    let stdout = root.join("native.stdout");
    let stderr = root.join("native.stderr");
    let child = Command::new("setsid")
        .arg(env!("CARGO_BIN_EXE_repository-host"))
        .args([
            "--cloudflare",
            &origin,
            "--repo",
            "demo",
            "--view-cache",
            "cold",
            root.join("host").to_str().unwrap(),
            "0",
        ])
        .stdout(File::create(&stdout).unwrap())
        .stderr(File::create(stderr).unwrap())
        .stdin(Stdio::null())
        .env("GIT_CONFIG_COUNT", "0")
        .env("GIT_TERMINAL_PROMPT", "0")
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .spawn()
        .unwrap();
    let mut native_process = Native(child);
    let native = (0..200)
        .find_map(|_| {
            assert!(
                native_process.0.try_wait().unwrap().is_none(),
                "native host exited"
            );
            if let Some(line) = fs::read_to_string(&stdout)
                .unwrap()
                .lines()
                .find(|line| line.starts_with("http://"))
            {
                return Some(line.trim_end_matches("/repo.git").to_owned());
            }
            std::thread::sleep(Duration::from_millis(100));
            None
        })
        .expect("native ready within 20 seconds");
    let gateway = format!("{origin}/demo/repo.git");
    let blob = text(
        &source,
        &["hash-object", "-w", "--stdin"],
        &payload(9 * 1024 * 1024, 0x1234_5678),
    );
    let mut tips = Vec::new();
    for revision in 1..=8 {
        let tip = commit(
            &source,
            tips.last().map(String::as_str),
            &blob,
            None,
            revision,
        );
        text(&source, &["update-ref", "refs/heads/main", &tip], &[]);
        git(
            &source,
            &[
                "-c",
                "protocol.version=0",
                "push",
                "--atomic",
                &gateway,
                "refs/heads/main:refs/heads/main",
                &format!("refs/heads/main:refs/heads/snapshot{revision:02}"),
            ],
            &[],
        );
        tips.push(tip);
    }
    // Bootstrap the existing R8 advertisement certificate from a true Full view.
    http(
        &root,
        "discovery",
        &format!("{gateway}/info/refs?service=git-upload-pack"),
        None,
    );
    let before = metrics(&root, "before-reads", &native, false);
    // Both real clients finish correctness and preserve receipts before the
    // activation assertion, so an unfixed binary records both failed cases.
    let real_no_haves = real_history_fetch(&root, &source, &native, &gateway, &tips[2], None);
    let real_with_haves =
        real_history_fetch(&root, &source, &native, &gateway, &tips[3], Some(&tips[1]));
    assert!(
        real_no_haves["projected"] == true && real_with_haves["projected"] == true,
        "real Git historical requests must select fewer R2 bytes; inspect real-*-receipt.json"
    );
    let latest_request = fetch(&tips[7], None, " ofs-delta");
    let latest = http(
        &root,
        "latest",
        &format!("{gateway}/git-upload-pack"),
        Some(&latest_request),
    );
    accept_pack(&client, &latest, &tips[7]);
    let no_haves = http(
        &root,
        "history-no-haves",
        &format!("{gateway}/git-upload-pack"),
        Some(&fetch(&tips[2], None, " ofs-delta")),
    );
    accept_pack(&client, &no_haves, &tips[2]);
    let selected = metrics(&root, "after-history-no-haves", &native, false);
    assert_projection(&selected);
    let with_haves = http(
        &root,
        "history-with-haves",
        &format!("{gateway}/git-upload-pack"),
        Some(&fetch(&tips[3], Some(&tips[2]), " ofs-delta")),
    );
    accept_pack(&client, &with_haves, &tips[3]);
    let selected = metrics(&root, "after-history-with-haves", &native, false);
    assert_projection(&selected);
    // A cached latest response must leave the prior projected view untouched.
    assert_eq!(
        latest,
        http(
            &root,
            "latest-recheck",
            &format!("{gateway}/git-upload-pack"),
            Some(&latest_request)
        )
    );
    let recheck = metrics(&root, "after-latest-recheck", &native, false);
    assert_projection(&recheck);
    assert_eq!(
        n(&recheck, "cloud_view_rehydrates"),
        n(&selected, "cloud_view_rehydrates")
    );
    assert_eq!(
        usage(&recheck, "r2_class_b"),
        usage(&selected, "r2_class_b")
    );
    let repeated_metrics = metrics(&root, "metrics-no-restore", &native, false);
    assert_projection(&repeated_metrics);
    assert_eq!(
        usage(&recheck, "r2_class_b"),
        usage(&repeated_metrics, "r2_class_b")
    );
    let restored = metrics(&root, "first-stats-restore", &native, true);
    assert_eq!(restored["native_view"]["scope"], "full");
    assert_eq!(
        n(&restored, "history_full_restores"),
        n(&recheck, "history_full_restores") + 1
    );
    let expected_gets: usize = restored["manifest"]["packs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pack| {
            ["pack", "index", "bundle"]
                .iter()
                .map(|key| pack[*key].as_array().map_or(0, Vec::len))
                .sum::<usize>()
        })
        .sum();
    assert_eq!(
        usage(&restored, "r2_class_b") - usage(&repeated_metrics, "r2_class_b"),
        expected_gets as u64
    );
    assert_no_storage_growth(&before, &restored);
    // Put the view back into Projection before a real >8 MiB incoming push.
    http(
        &root,
        "history-before-large",
        &format!("{gateway}/git-upload-pack"),
        Some(&fetch(&tips[1], None, " no-progress ofs-delta")),
    );
    let partial = metrics(&root, "before-large-push", &native, false);
    assert_projection(&partial);
    // Directly establish per-request no-op receipts while scope is partial;
    // the subsequent default Git client also sends its own real empty probe.
    let noop_body = http(
        &root,
        "partial-noop",
        &format!("{gateway}/git-receive-pack"),
        Some(b"0000"),
    );
    assert!(noop_body.is_empty());
    let noop = metrics(&root, "after-partial-noop", &native, false);
    assert_projection(&noop);
    assert_eq!(
        n(&noop, "cloud_view_rehydrates"),
        n(&partial, "cloud_view_rehydrates")
    );
    assert_eq!(usage(&noop, "r2_class_b"), usage(&partial, "r2_class_b"));
    assert_eq!(
        usage(&noop, "r2_read_bytes"),
        usage(&partial, "r2_read_bytes")
    );
    assert_eq!(
        n(&noop, "receive_noop_shortcuts"),
        n(&partial, "receive_noop_shortcuts") + 1
    );
    assert_no_storage_growth(&partial, &noop);
    let partial = noop;
    let extra = text(
        &source,
        &["hash-object", "-w", "--stdin"],
        &payload(10 * 1024 * 1024, 0x8765_4321),
    );
    let tip = commit(&source, Some(&tips[7]), &blob, Some(&extra), 9);
    text(&source, &["update-ref", "refs/heads/main", &tip], &[]);
    git(
        &source,
        &[
            "-c",
            "protocol.version=0",
            "push",
            "--atomic",
            &gateway,
            "refs/heads/main:refs/heads/main",
            "refs/heads/main:refs/heads/snapshot09",
        ],
        &[],
    );
    let pushed = metrics(&root, "after-large-push", &native, false);
    assert_eq!(pushed["native_view"]["scope"], "full");
    assert_eq!(
        n(&pushed, "cloud_view_rehydrates"),
        n(&partial, "cloud_view_rehydrates") + 1
    );
    // Git sends an empty receive probe followed by its chunked large push.
    // The exact empty probe consumes no object payload or native view change;
    // the following nonempty push performs one ordinary full reconstruction.
    assert_eq!(
        n(&pushed, "history_full_restores"),
        n(&partial, "history_full_restores") + 1
    );
    assert_eq!(n(&pushed, "requests"), n(&partial, "requests") + 3);
    assert_eq!(
        n(&pushed, "receive_noop_shortcuts"),
        n(&partial, "receive_noop_shortcuts") + 1
    );
    assert_eq!(
        usage(&pushed, "r2_class_b") - usage(&partial, "r2_class_b"),
        expected_gets as u64
    );
    assert_eq!(n(&pushed, "cache_bytes"), 0);
    let native_view = root.join("host/view/repo.git");
    git(&native_view, &["fsck", "--strict", "--full"], &[]);
    let response = http(
        &root,
        "large-latest",
        &format!("{gateway}/git-upload-pack"),
        Some(&fetch(&tip, None, " ofs-delta")),
    );
    accept_pack(&client, &response, &tip);
    text(&client, &["update-ref", "refs/heads/main", &tip], &[]);
    git(&client, &["fsck", "--strict", "--full"], &[]);
    assert_eq!(
        git(&source, &["archive", "--format=tar", &tip], &[]),
        git(&client, &["archive", "--format=tar", &tip], &[])
    );
    http(
        &root,
        "final-history",
        &format!("{gateway}/git-upload-pack"),
        Some(&fetch(&tips[2], Some(&tips[1]), " no-progress ofs-delta")),
    );
    let final_partial = metrics(&root, "final-partial", &native, false);
    assert_projection(&final_partial);
    let final_stats = metrics(&root, "final-stats-restore", &native, true);
    assert_eq!(final_stats["native_view"]["scope"], "full");
    assert_eq!(
        n(&final_stats, "history_full_restores"),
        n(&final_partial, "history_full_restores") + 1
    );
    assert_no_storage_growth(&pushed, &final_stats);
    fs::write(root.join("contract.json"), serde_json::to_vec_pretty(&serde_json::json!({
        "kind":"production_worker_correctness_not_benchmark", "worker_origin":origin,
        "source":"own worktree production index.js", "before":before, "first_restore":restored,
        "real_no_haves":real_no_haves,"real_with_haves":real_with_haves,
        "before_large_push":partial,"after_large_push":pushed,"final_partial":final_partial,"final_restore":final_stats,
        "fsck_strict":true,"archive_identical":true,"selected_corruption_tests":"separate unit tests; no silent full retry",
        "full_bill_cpu":null,"speed_claim":null
    })).unwrap()).unwrap();
}
